{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "The photos ranked by their green share, colored by how much of each is edges.",
  "mark": "bar",
  "encoding": {
    "y": {
      "field": "image_id",
      "type": "nominal",
      "sort": "-x",
      "title": "Photos, greenest first",
      "axis": {
        "labels": false,
        "ticks": false
      }
    },
    "x": {
      "field": "green_pct",
      "type": "quantitative",
      "title": "Green (% of pixels)"
    },
    "color": {
      "field": "edge_pct",
      "type": "quantitative",
      "title": "Edges (%)",
      "scale": {
        "scheme": "viridis"
      }
    },
    "tooltip": [
      {
        "field": "image_id"
      },
      {
        "field": "creator"
      },
      {
        "field": "green_pct"
      },
      {
        "field": "edge_pct"
      }
    ]
  }
}
